{tab==='Gmail'&&<><div className="section-title"><div><Badge tone="teal">CHAT-CONNECTED GMAIL / ASSISTED IMPORT</Badge><h2>Use your existing connected conversation</h2><p>Your plugin is already configured and tested. This app prepares requests and imports portable handoffs; it does not connect to or search your mailbox directly.</p></div></div><div className="form-grid"><label>Gmail query<input value={query} onChange={e=>setQuery(e.target.value)}/></label><label>Known label (optional, editable)<input value={label} onChange={e=>setLabel(e.target.value)} placeholder="No live label enumeration"/></label><label>After<input type="date" value={after} onChange={e=>setAfter(e.target.value)}/></label><label>Before<input type="date" value={before} onChange={e=>setBefore(e.target.value)}/></label><label>Maximum messages<input type="number" min={1} max={25} value={max} onChange={e=>setMax(Number(e.target.value))}/></label></div><button className="primary" onClick={()=>act(async()=>setRequest(await api('/api/gmail/prepare',{...context,scope:{query,label:label||null,after:after||null,before:before||null,max_messages:max}})),'Gmail request context frozen. Copy it to the connected conversation.')}><Copy size={15}/> Prepare Gmail Request</button>{request&&<div className="request-box"><p><b>Request {request.id}</b> · customer/environment versions frozen</p><textarea readOnly aria-label="Copyable Gmail request" rows={7} value={request.copyable_request}/><button onClick={()=>act(()=>navigator.clipboard.writeText(request.copyable_request),'Request copied.')}>Copy request</button> <button onClick={()=>act(async()=>{setHandoff(JSON.stringify(await api('/api/gmail/sample/'+request.id+'?customer_id='+customer),null,2));setHandoffPath('');setPreview(undefined)},'Synthetic sample loaded. This does not verify live Gmail retrieval.')}>Load synthetic handoff sample</button></div>}
<div className="divider">Import the returned versioned handoff</div><label className="file-input">Import Handoff file<input aria-label="Import Gmail handoff file" type="file" accept=".json" onChange={e=>e.target.files?.[0]&&act(()=>upload(e.target.files![0],true),'Handoff uploaded and previewed; process when ready.')}/></label><label>Or explicit local JSON path<input value={handoffPath} onChange={e=>{setHandoffPath(e.target.value);setPreview(undefined)}} placeholder="~/Downloads/gmail-handoff.json"/></label><label>Or paste schema-valid handoff JSON<textarea rows={6} value={handoff} onChange={e=>{setHandoff(e.target.value);setHandoffPath('');setPreview(undefined)}}/></label><div className="row"><button onClick={()=>act(async()=>setPreview(await api('/api/gmail/preview',raw())))}>Preview &amp; validate</button><button className="primary" disabled={!preview} onClick={()=>act(async()=>{let r=await api('/api/gmail/process',raw());setHandoffResult(r);setImports(await api('/api/gmail/imports?customer_id='+customer));return r},'Handoff processed with frozen request context.')}><ArrowRight size={15}/> Process handoff</button></div>{preview&&<div className="preview"><h3>Validated source preview</h3><p>{preview.messages.length} messages in file · {preview.pagination_status}</p>{preview.messages.map((m:Obj)=><details key={m.identity} open><summary>{m.subject} <Badge>{m.completeness}</Badge></summary><p>{m.sender} · {m.representation}</p><p className="gap">{m.gaps.join('; ')}</p><pre>{m.body}</pre></details>)}</div>}{handoffResult&&<details open><summary>Actual import counts and partial failures</summary><Json value={handoffResult}/></details>}<h3>Imported-message repository</h3><input aria-label="Filter imported messages" value={filter} onChange={e=>setFilter(e.target.value)} placeholder="Filter imported subject or sender (local only)"/>{imports.filter(i=>(i.subject+' '+i.sender).toLowerCase().includes(filter.toLowerCase())).map(i=><div className="history" key={i.id}><b>{i.subject}</b><small>{i.sender} · {i.representation} · {i.completeness}</small><code>{i.message_identity}</code></div>)}<p className="fine">Portable files are the intended transport. No shared filesystem, OAuth setup, callback or mailbox polling is assumed.</p></>}
