function CustomerEditor({c,boot,onSave}:Obj){const [name,setName]=useState(c.name),[sector,setSector]=useState(c.sector),[id,setId]=useState(c.id),[destination,setDestination]=useState(c.misp_destination||''),[live,setLive]=useState(c.allow_live_processing),[json,setJson]=useState(JSON.stringify({priorities:c.priorities,intelligence_requirements:c.intelligence_requirements,additional_sectors:c.additional_sectors,subsector:c.subsector,environments:c.environments},null,2)),[error,setError]=useState('');return <div className="panel padded"><h2>Edit or create a customer</h2><p>Each save creates a profile version. Jobs already running keep their original scope and destination. The sector list is the app’s initial taxonomy, not an official industry standard.</p><div className="form-grid"><label>Stable customer ID<input value={id} onChange={e=>setId(e.target.value)}/></label><label>Name<input value={name} onChange={e=>setName(e.target.value)}/></label><label>Primary sector<select value={sector} onChange={e=>setSector(e.target.value)}>{Object.entries(boot.sectors).map(([id,label])=><option key={id} value={id}>{String(label)}</option>)}</select></label><label>MISP destination (optional)<input value={destination} onChange={e=>setDestination(e.target.value)} placeholder="https://your-misp.example"/></label></div><label className="check"><input type="checkbox" checked={live} onChange={e=>setLive(e.target.checked)}/> Allow selected source spans to configured live model</label><label>Environment, telemetry, controls and customer requirements (editable JSON)<textarea className="mono" rows={22} value={json} onChange={e=>setJson(e.target.value)}/></label><div className="row"><button onClick={()=>{try{let obj=JSON.parse(json);const t=boot.templates.find((x:Obj)=>!obj.environments.some((e:Obj)=>e.id===x.id));if(!t)throw Error('Both seed templates already selected. Edit JSON for a distinct environment.');obj.environments.push(t);setJson(JSON.stringify(obj,null,2))}catch(e){setError(String(e))}}}>Add other environment template</button><button className="primary" onClick={()=>{try{const obj=JSON.parse(json);onSave({...c,...obj,id,name,sector,misp_destination:destination||null,allow_live_processing:live})}catch(e){setError(String(e))}}}>Save profile version</button><button onClick={()=>{setId('customer-'+Date.now());setName('New fictional customer')}}>Create new profile from this</button></div>{error&&<p role="alert">{error}</p>}</div>}
function ActionForm({a,customer,act,done,improvement,candidate,edit}:Obj){const [kind,setKind]=useState(improvement&&!edit?'test':'improvement'),[method,setMethod]=useState('analyst attestation'),[saving,setSaving]=useState(false);const defaults=candidate?.prefill||(edit?improvement:undefined);const submitLock=useRef(false);async function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();if(submitLock.current)return;submitLock.current=true;setSaving(true);let data=Object.fromEntries(new FormData(e.currentTarget));let body:Obj={customer_id:customer,environment_id:a.context.environment_id};if(kind==='improvement'){body.action={behavior_id:candidate?.behavior_id||improvement?.origin?.behavior_id||data.behavior,owner:data.owner,priority:data.priority,status:candidate?'open':data.status,rationale:data.rationale,proposed_change:data.change,retest:data.retest,...(edit?{id:improvement.id,origin:improvement.origin}: {})};if(candidate)body.candidate_ref={snapshot_id:candidate.snapshot_id,candidate_id:candidate.id};}else{body.test={behavior_id:improvement?.origin?.behavior_id||data.behavior,environment_version:a.context.environment_version,control_id:data.control,control_version:data.version,procedure:data.procedure,expected:data.expected,actual:data.actual,executed_at:data.time,method,result:data.result,dimension:data.dimension,scope:data.scope,variant:data.variant,exercise:data.exercise,baseline:data.baseline==='on',control_deployed_at:data.deployed||null,improvement_id:improvement?.id||null,exercise_event_at:data.exercise_time||null,attempted_action:data.attempt||null,control_outcome:data.outcome||null,evidence:[{id:'operator-reference-'+Date.now(),reference:data.evidence,description:data.description,kind:method==='synthetic log match'?'synthetic fixture replay':data.evidence_kind}]};}let r=await act(()=>api('/api/ledger/'+a.id+'/'+(kind==='improvement'?'improve':'test'),body));submitLock.current=false;setSaving(false);if(r)done()}
return <><div className="eyebrow">APPEND EVIDENCE, PRESERVE HISTORY</div><h2>{candidate?'Review defensive improvement':edit?'Edit improvement':'Record an improvement or test'}</h2><p className="fine">Frozen customer v{a.context.customer_version} · Environment v{a.context.environment_version}. Saving an improvement does not verify protection.</p><DefenseOrigin origin={improvement?.origin}/><div className="tabs">{(candidate||edit?['improvement']:['improvement','test']).map(k=><button className={kind===k?'selected':''} key={k} onClick={()=>setKind(k)}>{k}</button>)}</div><form onSubmit={submit}><label>Behavior<select name="behavior" disabled={!!candidate||!!improvement?.origin} defaultValue={candidate?.behavior_id||improvement?.behavior_id}>{a.extraction.behaviors.map((b:Obj)=><option key={b.id} value={b.id}>{b.text}</option>)}</select></label>{kind==='improvement'?<><ImprovementFields defaults={defaults} lockedNew={!!candidate}/></>:<><label>Method<select name="method" value={method} onChange={e=>setMethod(e.target.value)}>{['analyst attestation','synthetic log match','lab emulation','observed SIEM alert','observed prevention'].map(m=><option key={m}>{m}</option>)}</select></label><div className="form-grid"><label>Dimension<select name="dimension">{['detection','telemetry','prevention','deployment','soc_acknowledged','soc_response'].map(x=><option key={x}>{x}</option>)}</select></label><label>Result<select name="result"><option>failed</option><option>inconclusive</option><option>passed</option></select></label><label>Control / rule ID<input name="control" required/></label><label>Control / rule version<input name="version" required/></label></div><label>Variant tested<input name="variant" required/></label><label>Scope<input name="scope" required placeholder="Named lab host / synthetic event only"/></label><label>Procedure<textarea required name="procedure"/></label><label>Expected outcome<input required name="expected"/></label><label>Actual outcome<textarea required name="actual"/></label><label>Executed at (timezone required)<input name="time" required defaultValue={new Date().toISOString()}/></label><label>Evidence reference<input name="evidence" required placeholder="Evidence file hash / immutable lab record URI"/></label><label>Evidence description<input name="description" required/></label><label>Evidence kind<select name="evidence_kind">{['analyst attestation','lab execution','live system','synthetic fixture replay'].map(x=><option key={x}>{x}</option>)}</select></label><label>Exercise<select name="exercise"><option>coordinated</option><option>blind</option></select></label><label>Exercise event/alert time (required for SOC)<input name="exercise_time"/></label><label>Attempted action (required for prevention)<input name="attempt"/></label><label>Enforcing control outcome<input name="outcome"/></label><label className="check"><input name="baseline" type="checkbox"/> Confirm existing baseline evidence</label><label>Original control deployment time<input name="deployed" defaultValue={improvement?.deployed_at||''} placeholder="Optional UTC timestamp"/></label><p className="fine">Assertions stay attestations. Synthetic passes cannot become live detection, prevention, or SOC evidence. Existing test timestamps are never rewritten.</p></>}<button className="primary" disabled={saving}>{saving?'Saving…':edit?'Save improvement':'Record '+kind}</button></form></>}
